export default function plan({ body }) {
  const m = body?.message,
    id = m?.chat?.id;
  if (!Number.isSafeInteger(id)) throw Error("Missing Telegram chat");
  const photos = m?.photo;
  if (photos == null || (Array.isArray(photos) && photos.length === 0))
    return { chatId: id, hasPhoto: false, fileId: "unused", fileRequest: {} };
  if (!Array.isArray(photos)) throw Error("Invalid Telegram photos");
  const photo = photos.at(-1);
  if (typeof photo?.file_id !== "string" || !photo.file_id) throw Error("Missing photo file ID");
  return {
    chatId: id,
    hasPhoto: true,
    fileId: photo.file_id,
    fileRequest: { file_id: photo.file_id },
  };
}

