import { Buffer } from "node:buffer";
export default async function download({ botToken, verified, reply, statusCode, fileId }, context) {
  if (verified !== true || typeof botToken !== "string" || !/^\d+:[A-Za-z0-9_-]+$/.test(botToken))
    throw Error("Verify the Telegram bot token");
  const f = reply?.result,
    path = f?.file_path;
  if (
    statusCode !== 200 ||
    reply?.ok !== true ||
    f?.file_id !== fileId ||
    typeof path !== "string" ||
    !/^photos\/[A-Za-z0-9_.-]+\.jpe?g$/i.test(path)
  )
    throw Error("Telegram did not confirm a valid photo path");
  try {
    const r = await context.fetch(
      "https://api.telegram.org/file/bot" +
        botToken +
        "/" +
        path.split("/").map(encodeURIComponent).join("/"),
      { method: "GET" },
    );
    if (!r.ok) throw Error("Download failed");
    const bytes = new Uint8Array(await r.arrayBuffer());
    if (
      !bytes.length ||
      bytes.length > 700000 ||
      bytes[0] !== 255 ||
      bytes[1] !== 216 ||
      bytes[2] !== 255 ||
      (typeof f.file_size === "number" && f.file_size !== bytes.length)
    )
      throw Error("Invalid photo");
    return { image: "data:image/jpeg;base64," + Buffer.from(bytes).toString("base64") };
  } catch {
    throw Error("Telegram photo download failed or exceeds the supported size");
  }
}

