export default function answer({ response }) {
  if (!response || response.status !== "completed" || !Array.isArray(response.output))
    throw Error("Image analysis did not complete");
  const texts = response.output.flatMap((x) =>
      Array.isArray(x.content)
        ? x.content
            .filter((y) => y.type === "output_text" && typeof y.text === "string")
            .map((y) => y.text)
        : [],
    ),
    text = texts.join("\n").trim();
  if (!text || text.length > 4096) throw Error("Image analysis response is empty or too long");
  return { text };
}
